// Map each sheet row into the JSON shape the MapLibre map expects.
const pharmacies = items.map(item => {
  const row = item.json;
  return {
    name: row['Pharmacy Name'] || '',
    address: row['Address'] || '',
    lat: row['Latitude'] ? parseFloat(row['Latitude']) : null,
    lng: row['Longitude'] ? parseFloat(row['Longitude']) : null,
    mmm: row['MMM'] || '',
    contactPerson: row['Contact Person'] || '',
    email: row['Email'] || '',
    phone: row['Phone'] || '',
    services: row['Services & Experience Offered'] || '',
    accommodation: row['Accommodation'] || '',
    internPosition: row['Intern Pharmacist Position'] || ''
  };
});

return [{ json: { pharmacies } }];

const originalItems = $('Merge Cached Coords').all();
const geocodeItems = items;

const geocodeByIndex = {};
for (const item of geocodeItems) {
  const idx = item.pairedItem && typeof item.pairedItem.item === 'number' ? item.pairedItem.item : null;
  if (idx !== null) geocodeByIndex[idx] = item.json;
}

function simplifyAddress(address) {
  const parts = address.split(',').map(p => p.trim()).filter(Boolean);
  if (parts.length <= 2) return address;
  return parts.slice(-2).join(', ');
}

async function geocode(address) {
  const url = 'https://nominatim.openstreetmap.org/search?format=json&limit=1&q=' + encodeURIComponent(address);
  const res = await this.helpers.httpRequest({
    url,
    method: 'GET',
    headers: { 'User-Agent': 'NAPSA-Rural-Placement-Map/1.0' },
    json: true
  });
  return Array.isArray(res) && res.length > 0 ? res[0] : null;
}

const results = [];
for (let idx = 0; idx < originalItems.length; idx++) {
  const original = originalItems[idx].json;
  let lat = original['Latitude'] ? parseFloat(original['Latitude']) : null;
  let lng = original['Longitude'] ? parseFloat(original['Longitude']) : null;

  if (!lat || !lng) {
    const geo = geocodeByIndex[idx];
    if (geo && geo.lat && geo.lon) {
      lat = parseFloat(geo.lat);
      lng = parseFloat(geo.lon);
    }
  }

  if (!lat || !lng) {
    const simplified = simplifyAddress(original['Address'] || '');
    try {
      const retryResult = await geocode.call(this, simplified);
      if (retryResult) {
        lat = parseFloat(retryResult.lat);
        lng = parseFloat(retryResult.lon);
      }
    } catch (e) {
      // leave null - will need manual coordinates
    }
    await new Promise(resolve => setTimeout(resolve, 1100));
  }

  results.push({ json: { ...original, Latitude: lat, Longitude: lng } });
}

return results;

const cachedRows = items.map(item => item.json);
const pharmacyRows = $('Get Pharmacies').all();

const cacheByName = {};
for (const row of cachedRows) {
  cacheByName[row.pharmacyName] = row;
}

return pharmacyRows.map(item => {
  const row = item.json;
  const cached = cacheByName[row['Pharmacy Name']];
  return {
    json: {
      ...row,
      Latitude: cached && cached.latitude != null ? cached.latitude : null,
      Longitude: cached && cached.longitude != null ? cached.longitude : null
    }
  };
});

